input.command:
mkdir -p /tmp/claude-0/shot && cat > /tmp/claude-0/shot/shoot.mjs <<'EOF'
// One parameterised driver: node shoot.mjs <url> <out.png> [prep.js]
// `prep.js` is evaluated in the page before the shot, so one driver covers every
// state the page has rather than a throwaway script per screenshot.
import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';

const [url, out, prep] = process.argv.slice(2);
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1100, height: 760 } });
page.on('console', (m) => process.stderr.write(`[console:${m.type()}] ${m.text()}\n`));
page.on('pageerror', (e) => process.stderr.write(`[pageerror] ${e.message}\n`));
await page.goto(url, { waitUntil: 'networkidle' });
if (prep) await page.evaluate(readFileSync(prep, 'utf8'));
await page.waitForTimeout(200);
await page.screenshot({ path: out });
await browser.close();
process.stdout.write(`shot ${out}\n`);
EOF
cd /tmp/claude-0/shot && npm init -y >/dev/null 2>&1 && npm i playwright >/dev/null 2>&1; node -e "import('playwright').then(()=>console.log('playwright ok'))"

