// The account menu as a signed-in viewer meets it. The page hides it until
// `getViewer` returns, which needs network, so the same two fields that call
// sets are set here and the panel is opened.
document.getElementById('account').hidden = false;
document.getElementById('account-login').textContent = 'missingbulb';
document.getElementById('account-avatar').removeAttribute('src');
document.getElementById('account').open = true;
const pill = document.getElementById('rate');
pill.hidden = false;
pill.textContent = '4867/5000 · user · −133 this load';
EOF
